insert into static_destination_places (country_code, static_dest_id, name, name_latin, image_url, category, source, cuisine_tags, budget_level, address, lat, lng, geoapify_place_id)
select r.country_code, r.static_dest_id, r.name, r.name_latin, null, 'restaurant', 'editorial', r.cuisine_tags, r.budget_level, r.address, r.lat, r.lng, r.geoapify_place_id
from editorial_restaurants r
where not exists (
  select 1 from static_destination_places e
  where e.country_code=r.country_code and e.static_dest_id=r.static_dest_id and e.category='restaurant'
    and (e.geoapify_place_id=r.geoapify_place_id or lower(trim(coalesce(e.name_latin,e.name)))=lower(trim(coalesce(r.name_latin,r.name))))
);

commit;
